import {test} from 'node:test';
import assert from 'node:assert/strict';
import {HeartbeatTelemetry} from '../src/mavlink.js';
// Independent wire fixtures generated by pymavlink's ardupilotmega dialect.
const manual=Buffer.from('fe0900010100000000000a038104035d04','hex');
const guided=Buffer.from('fd0900000001010000000f0000000a030104037547','hex');
test('heartbeat decodes v1/v2 arm and Rover modes, invalid data cannot refresh freshness',()=>{
 const t=new HeartbeatTelemetry({systemId:1,timeoutMs:3000});
 assert.equal(t.snapshot(0).connected,false);
 t.receive(manual,100);assert.deepEqual(t.snapshot(100),{connected:true,armed:true,flightMode:'MANUAL',customMode:0,ageMs:0});
 t.receive(guided,200);assert.equal(t.snapshot(200).armed,false);assert.equal(t.snapshot(200).flightMode,'GUIDED');
 const corrupt=Buffer.from(manual);corrupt[8]^=1;t.receive(corrupt,3000);
 t.receive(manual.subarray(0,10),3000);
 assert.equal(t.snapshot(3201).connected,false);assert.equal(t.snapshot(3201).armed,null);
 assert.equal(t.snapshot(3201).flightMode,null);
 t.receive(Buffer.concat([Buffer.from([1,2]),manual,guided]),4000);assert.equal(t.snapshot(4000).flightMode,'GUIDED');
 t.receive(Buffer.from('fd090000000101000000630000000a03810403604e','hex'),4100);
 assert.equal(t.snapshot(4100).flightMode,'MODE 99');
 const other=new HeartbeatTelemetry({systemId:2});other.receive(manual,100);assert.equal(other.snapshot(100).connected,false);
});
